 std::cout<<"PASS Kit/Pattern/Role locks override global Dice\n";
 {Host h;auto&p=*h.p;for(int b=0;b<4;++b)p.set(G::performanceLock(b+4),1);p.set(kRandomAmt,100);p.set(kFillSlot,2);for(auto&n:p.notes[2])n.data.store(0);for(int b=0;b<4;++b)p.set(G::performanceLock(b+4),1);auto fills=fillSnapshot(p);auto fx=fxSnapshot(p);auto seed=p.partSeed[0].load();int kit=p.getInt(kXKit);h.pulse(kRollFill);assert(p.countNotes(2)>0&&p.partSeed[0].load()==seed&&fxSnapshot(p)==fx&&p.getInt(kXKit)==kit);for(int b:{0,1,3})for(int i=0;i<128;++i)assert(p.notes[b][i].data.load()==fills[b*257+1+i*2]);h.pulse(kPerformUndo);assert(fillSnapshot(p)==fills);auto state=p.internalSaveState();h.render();assert(fillSnapshot(p)==fills&&fxSnapshot(p)==fx);h.pulse(kRollFx);assert(fxSnapshot(p)!=fx&&fillSnapshot(p)==fills&&p.partSeed[0].load()==seed);h.pulse(kUndo);assert(fxSnapshot(p)==fx);assert(p.internalLoadState(state.data(),state.size()));assert(!p.getBool(kRollFill)&&!p.getBool(kRollFx));}
