 {Host h;auto&p=*h.p;for(int b=0;b<4;++b)p.set(G::performanceLock(b+4),1);p.set(kRandomAmt,0);for(int b=0;b<4;++b)p.set(G::performanceLock(b+4),1);auto fills=fillSnapshot(p);auto fx=fxSnapshot(p);h.pulse(kRollFill);h.pulse(kRollFx);assert(fillSnapshot(p)==fills&&fxSnapshot(p)==fx);p.set(kRandomAmt,100);p.recordState.store(2);h.pulse(kRollFill);assert(fillSnapshot(p)==fills);}
 {Host h;auto&p=*h.p;for(int b=0;b<4;++b)p.set(G::performanceLock(b+4),1);for(int i=0;i<16;++i)p.set(kDiceLock0+i,1);for(int k:kExtraDiceValueLocks)p.set(k,1);p.set(kKitLock,1);p.set(kPatternLock,1);p.set(kRoleLock0,1);for(int b=0;b<4;++b)p.set(G::performanceLock(b+4),1);auto fills=fillSnapshot(p);auto fx=fxSnapshot(p);float swing=p.get(kSwing);h.pulse(kUnlockDice);for(int i=0;i<16;++i)assert(!p.getBool(kDiceLock0+i));for(int k:kExtraDiceValueLocks)assert(!p.getBool(k));assert(!p.getBool(kKitLock)&&!p.getBool(kPatternLock)&&!p.getBool(kRoleLock0));assert(fillSnapshot(p)==fills&&fxSnapshot(p)==fx&&p.get(kSwing)==swing);}
 {Host h;auto&p=*h.p;for(int b=0;b<4;++b)p.set(G::performanceLock(b+4),1);p.set(kRandomAmt,100);for(int key:{kRollFill,kRollFx}){h.pulse(key);assert(p.getNormalised(key)==0);auto fill=fillSnapshot(p);auto fx=fxSnapshot(p);for(int n=0;n<10;++n)h.render();assert(fillSnapshot(p)==fill&&fxSnapshot(p)==fx);h.pulse(key);assert(p.getNormalised(key)==0);auto state=p.internalSaveState();assert(p.internalLoadState(state.data(),state.size())&&p.getNormalised(key)==0);}}
